<template>
  <q-page class="page">
    <div class="row items-end justify-between q-mb-lg"><div><div class="eyebrow">{{ route.meta.group }}</div><h1>{{ route.meta.title }}</h1><p class="muted">Live data from the Mini Banking System API.</p></div><q-btn v-if="canCreate" color="primary" icon="add" label="New record" @click="openCreate" /></div>
    <q-banner v-if="error" class="notice q-mb-md" rounded><q-icon name="warning" /> {{ error }}</q-banner>
    <q-table flat bordered :rows="rows" :columns="columns" row-key="id" :loading="loading" :pagination="{ rowsPerPage: 10 }" no-data-label="No records found"><template #body-cell-actions="props"><q-td :props="props"><q-btn v-if="canEdit" flat round dense icon="edit" color="primary" @click="openEdit(props.row)" /><q-btn v-if="canDelete" flat round dense icon="delete" color="negative" @click="remove(props.row)" /><q-btn v-if="route.meta.endpoint === '/interbank-transfers/' && props.row.status === 'PROCESSING'" flat round dense icon="check_circle" color="positive" @click="setStatus(props.row, 'SUCCESS')" /><q-btn v-if="route.meta.endpoint === '/interbank-transfers/' && props.row.status === 'PROCESSING'" flat round dense icon="cancel" color="negative" @click="setStatus(props.row, 'FAILED')" /></q-td></template></q-table>
    <q-dialog v-model="dialog"><q-card class="form-card"><q-card-section><div class="text-h6">{{ editing ? 'Edit' : 'Create' }} {{ route.meta.title }}</div><div class="muted text-caption q-mt-sm">Enter a JSON request body matching the API schema.</div></q-card-section><q-card-section><q-input v-model="payload" type="textarea" outlined autogrow :error="Boolean(parseError)" :error-message="parseError" /><div class="row justify-end q-gutter-sm q-mt-md"><q-btn flat label="Cancel" v-close-popup /><q-btn color="primary" label="Save" :loading="saving" @click="save" /></div></q-card-section></q-card></q-dialog>
  </q-page>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue'; import { useRoute } from 'vue-router'; import { useQuasar } from 'quasar'; import api from 'src/services/api'; import { useAuthStore } from 'src/stores/auth-store'
const route = useRoute(); const $q = useQuasar(); const auth = useAuthStore(); const rows = ref([]); const loading = ref(false); const saving = ref(false); const dialog = ref(false); const editing = ref(null); const payload = ref(''); const error = ref(''); const parseError = ref('');
const canCreate = computed(() => !['/sessions/', '/interest-records/', '/ledger-entries/'].includes(route.meta.endpoint) || auth.isAdmin); const canEdit = computed(() => !['/audit-logs/', '/interest-records/', '/ledger-entries/'].includes(route.meta.endpoint)); const canDelete = computed(() => true)
const columns = computed(() => { const row = rows.value[0] || {}; return Object.keys(row).filter((key) => key !== 'id').map((name) => ({ name, label: name.replaceAll('_', ' ').toUpperCase(), field: name, align: 'left' })).concat([{ name: 'actions', label: '', field: 'actions', align: 'right' }]) })
function openCreate () { editing.value = null; payload.value = JSON.stringify({}, null, 2); parseError.value = ''; dialog.value = true }
function openEdit (row) { editing.value = row.id; const copy = { ...row }; delete copy.id; delete copy.created_at; delete copy.updated_at; delete copy.opened_at; delete copy.closed_at; delete copy.initiated_at; delete copy.completed_at; delete copy.charged_at; delete copy.credited_at; delete copy.action_timestamp; delete copy.login_at; payload.value = JSON.stringify(copy, null, 2); parseError.value = ''; dialog.value = true }
async function load () { loading.value = true; error.value = ''; try { rows.value = (await api.get(route.meta.endpoint)).data } catch (e) { error.value = e.response?.data?.detail || 'Could not load records. Check that the backend database and layer are available.' } finally { loading.value = false } }
async function save () { let data; try { data = JSON.parse(payload.value); parseError.value = '' } catch { parseError.value = 'Enter valid JSON'; return } saving.value = true; try { if (editing.value) await api.put(`${route.meta.endpoint}${editing.value}`, data); else await api.post(route.meta.endpoint, data); dialog.value = false; $q.notify({ type: 'positive', message: 'Saved successfully' }); await load() } catch (e) { $q.notify({ type: 'negative', message: e.response?.data?.detail || 'Could not save record' }) } finally { saving.value = false } }
function remove (row) { $q.dialog({ title: 'Confirm delete', message: `Delete record #${row.id}?`, cancel: true }).onOk(async () => { try { await api.delete(`${route.meta.endpoint}${row.id}`); await load() } catch (e) { $q.notify({ type: 'negative', message: e.response?.data?.detail || 'Could not delete record' }) } }) }
async function setStatus (row, status) { try { await api.put(`/interbank-transfers/${row.id}/status`, { status }); await load() } catch (e) { $q.notify({ type: 'negative', message: e.response?.data?.detail || 'Could not update status' }) } }
onMounted(load); watch(() => route.meta.endpoint, load)
</script>
